.work/frame-stall-followup/frozen-baseli.source:
import { build } from 'vite';
import { execFileSync } from 'node:child_process';
import { resolve, relative } from 'node:path';

const root = process.cwd();
const baseline = '7b2afaf99f12f69773f598e1d1401a9fbe9583e9';
await build({
  root,
  build: { outDir: '.work/frame-stall-followup/before-dist' },
  plugins: [{
    name: 'frozen-followup-baseline', enforce: 'pre',
    load(id) {
      const path = id.split('?')[0];
      if (!path.startsWith(resolve(root, 'src') + '/') || !path.endsWith('.ts')) return;
      return execFileSync('git', ['show', `${baseline}:${relative(root, path)}`], { encoding: 'utf8' });
    },
  }],
});

