import { createServer } from 'vite';
import { chromium } from '@playwright/test';
import { readFile, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { resolve } from 'node:path';
const root = process.cwd(), folder = resolve(root, '.work/frame-stall-followup');
const baselineFile = resolve(folder, 'desk-clock-before.ts');
const oldSource = await readFile(baselineFile, 'utf8');
const beforeHash = createHash('sha256').update(oldSource).digest('hex');
const afterHash = createHash('sha256').update(await readFile(resolve(root, 'src/desk-clock.ts'))).digest('hex');
const server = await createServer({ root, configFile: false, server: { host: '127.0.0.1', port: 5195, strictPort: true },
  plugins: [{ name: 'frozen-clock-component', resolveId(id) {
    if (id === '/__clock_baseline.ts' || id === '/__clock_three.ts') return id;
  }, load(id) {
    if (id === '/__clock_baseline.ts') return oldSource.replace('"./desk-clock-time"', '"/src/desk-clock-time.ts"');
    if (id === '/__clock_three.ts') return "export * from 'three';";
  } }], optimizeDeps: { include: ['three'] }, logLevel: 'error' });
let browser;
const report = { schema: 1, kind: 'native-clock-component-microbenchmark', baseline: '7b2afaf',
 startedAtUTC: new Date().toISOString(), sourceHashes: { before: beforeHash, after: afterHash }, method: {
  repetitions: 3, order: 'Alternating before/after order for each repetition, each variant uses a fresh browser context, clock model and WebGLRenderer.',
  cpuThrottle: 4, warmups: 5, measuredMinutes: 24, viewport: [64,64], rendererCanvas: [16,16],
